import time


class CircuitOpenError(Exception):
    """Raised by CircuitBreaker.call instead of calling the function while the circuit is open."""


class CircuitBreaker:
    def __init__(self, failure_threshold, cooldown, clock=time.monotonic):
        self._failure_threshold = failure_threshold
        self._cooldown = cooldown
        self._clock = clock
        self._failures = 0              # failures in a row while closed
        self._opened_at = None          # when the circuit last opened; None while it is closed
        self._trial_running = False     # True while the single half-open trial call is in progress

    @property
    def state(self):
        if self._opened_at is None:
            return "closed"
        if self._clock() - self._opened_at >= self._cooldown:
            return "half_open"
        return "open"

    def call(self, fn, *args, **kwargs):
        state = self.state
        if state == "open" or (state == "half_open" and self._trial_running):
            raise CircuitOpenError("circuit is open, the call was not made")
        trial = state == "half_open"
        if trial:
            self._trial_running = True
        try:
            result = fn(*args, **kwargs)
        except Exception:
            self._failures += 1
            if trial or self._failures >= self._failure_threshold:
                self._opened_at = self._clock()     # (re)open, and start the cool-down now
            raise
        else:
            self._failures = 0
            self._opened_at = None                  # a success closes the circuit
            return result
        finally:
            if trial:
                self._trial_running = False
